/**
 * CGo OpenMap - 福州官方站间票价表 (city/fuzhou/data_official_fare.js)
 *
 * 数据来源：福州地铁官网「票价线路查询」
 *   GET https://www.fzmtr.com/api/system/way/list?pageNum=1&pageSize=10
 *       &startStation={起点站名}&endStation={终点站名}
 * 抓取时间：见下方 FUZHOU_OFFICIAL_FARE_META.fetchedAt
 * 覆盖：官方 6 条线 102 座车站的两两组合（102 × 102，含未开通站除外的全部运营车站），
 *       共 10302 组，逐对含票价（元）、路径说明与是否含大站快车。
 *
 * 为什么要用官方表而不是纯计算：站距数据（data_lines.js，OSM 轨道里程）与官方计费里程
 * 在档位分界附近有 0.2~1.7 km 量级的差异，按计算式会有约 3% 的组合落在相邻档位
 * （±1 元）。官方表是权威口径，故行程规划与票价图**优先查表**，
 * 查不到（未开通车站、或表格未覆盖的组合）时回落到 fuzhou.js 里的两段式计算规则。
 *
 * 结构：FUZHOU_OFFICIAL_FARE["起点ID|终点ID"] = 票价（元）
 *   · 键用车站 ID（与 data_stations.js 一致），加载时由官方站名映射而来；
 *   · 官方未收录的未开通车站（莲花 / 壶井 / 滨海西）不会出现在表里。
 * 另附 FUZHOU_OFFICIAL_SEGMENT_FARE[]：同线相邻站对的官方票价，用于自检里程口径。
 *
 * 维护提示：官网票价调整后请重新抓取本文件（抓取接口与步骤见
 * city/fuzhou/tools/fuzhou_check.js 的文件头说明），并递增 sw.js 的 CACHE_NAME。
 */

const FUZHOU_OFFICIAL_FARE_META = {
    source: "https://www.fzmtr.com/services/routeQuery",
    api: "https://www.fzmtr.com/api/system/way/list",
    fetchedAt: "2026-10-02",
    stationCount: 102,
    pairCount: 10302
};

